package com.shipflow.tracking;import com.shipflow.tracking.application.*;import com.shipflow.tracking.domain.*;import com.shipflow.tracking.mapper.*;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class TrackingQueryApplicationServiceTest{@Test void listsTenantEventsAndReturnsLatestStatus(){TrackingQueryMapper m=mock(TrackingQueryMapper.class);when(m.orderExists(7L,9L)).thenReturn(true);var first=new TrackingEvent(1L,"T","PICKED",null,LocalDateTime.of(2026,1,1,1,0),"PROCESSED");var latest=new TrackingEvent(2L,"T","DELIVERED",null,LocalDateTime.of(2026,1,2,1,0),"PROCESSED");when(m.findEvents(7L,9L)).thenReturn(List.of(first,latest));when(m.currentStatus(7L,9L)).thenReturn("DELIVERED");when(m.findLatest(7L,9L)).thenReturn(latest);var s=new TrackingQueryApplicationService(m);assertThat(s.list(7L,9L)).extracting(x->x.id()).containsExactly(1L,2L);assertThat(s.status(7L,9L).latestEvent().eventCode()).isEqualTo("DELIVERED");}}
